  // G2-2: Visão Geral - Composição Setorial do PIB (Donut com Filtro de Ano 2002 a 2023)
  async function renderGeralPibSetorialChart(selectedYear) {
    const gt=RADAR_HUB_CACHE.groundTruth; const years=gt?.eixos?.economia?.pib_serie_historica?.map(r=>String(r.ano)) || [];
    const year=String(selectedYear || '2021'); if(!years.includes(year)) return;
    RADAR_HUB_CACHE.selectedGeralPibYear=year;
    const available = gt?.eixos?.economia?.pib_serie_historica?.filter(r => r.components_mil_reais?.servicos != null).map(r => String(r.ano)) || [];
    document.querySelectorAll('.filter-pill-pib-year').forEach(btn=>{btn.disabled=!available.includes(String(btn.dataset.year));btn.classList.toggle?.('hidden',btn.disabled);});
    const notice=document.getElementById('pib-setorial-notice-block'); if(notice) { notice.classList.add('hidden');notice.classList.remove('flex'); }
    economicSectorChart(gt,'hubChartGeralPibSetorial',year);
  }

  // G2: Visão Geral - PIB Geral & Composição Setorial
  function renderGeralPibChart(gt) {
    renderGeralPibTotalChart();
    renderGeralPibSetorialChart(RADAR_HUB_CACHE.selectedGeralPibYear || '2021');
  }

