  function economicIndicator(id) {
    const i = RADAR_HUB_CACHE.metadataRegistry?.indicators.find(x => x.indicator_id === id);
    const a = RADAR_HUB_CACHE.package?.economiaAudit?.indicators?.[id];
    return i && a && ['VALIDADO_EXTERNAMENTE','CALCULADO_A_PARTIR_DE_FONTES_OFICIAIS'].includes(a.status) &&
      i.audit_status === a.status && i.value != null && i.value === a.value &&
      i.evidence_id === a.evidence_id && (i.competencia || i.base_year) === a.period ? i : null;
  }
  function economicNote(canvasId, text) {
    const canvas = document.getElementById(canvasId);
    let note = document.getElementById(canvasId+'-evidence');
    if (!note && canvas?.parentNode) {
      note = document.createElement('p'); note.id = canvasId+'-evidence';
      note.className = 'text-[10px] text-slate-500 mt-2';
      if (canvas.parentNode.insertAdjacentElement) canvas.parentNode.insertAdjacentElement('afterend',note);
      else canvas.parentNode.appendChild(note);
    }
    if (note) note.textContent = text;
  }
  function drawEconomicChart(canvasId, type, labels, datasets, note) {
    const canvas = document.getElementById(canvasId); if (!canvas || !window.Chart) return;
    destroyChart(canvasId); hideChartFallback(canvasId);
    const any = datasets.some(d => d.data.some(v => v != null));
    economicNote(canvasId,note);
    if (!any) { showChartFallback(canvasId,null,canvasId.includes('Empresas') ? 'https://www.gov.br/receitafederal/dados' : 'https://ftp.ibge.gov.br/Pib_Municipios/2022_2023/base/',canvasId.includes('Empresas') ? 'Receita Federal' : 'IBGE',note); hideSkeleton(canvasId); return; }
    RADAR_HUB_CACHE.charts[canvasId] = new Chart(canvas.getContext('2d'), {
      type, data:{labels,datasets}, options:{responsive:true,maintainAspectRatio:false,
        plugins:{legend:{display:true,position:'top'},datalabels:{display:false},
          tooltip:{callbacks:{label:c => `${c.dataset.label || c.label}: ${c.raw == null ? 'Dado não disponível' : Number(c.raw).toLocaleString('pt-BR',{maximumFractionDigits:6})}`,footer:()=>note}}},
        ...(type==='doughnut' ? {cutout:'62%'} : {scales:{y:{beginAtZero:false}}})}
    }); hideSkeleton(canvasId);
  }
  function economicPibChart(gt, canvasId, tipo='total') {
    const serie = gt?.eixos?.economia?.pib_serie_historica || [];
    const perCapita = tipo==='per_capita';
    const values = serie.map(s => perCapita ? s.pib_per_capita ?? null : s.pib_milhoes == null ? null : s.pib_milhoes/1000);
    drawEconomicChart(canvasId,'line',serie.map(s=>String(s.ano)),[{label:perCapita?'PIB per capita (R$/habitante)':'PIB nominal (R$ bilhões)',data:values,borderColor:'#0284C7',backgroundColor:'#0284C733',tension:0,spanGaps:false}],
      'IBGE — PIB dos Municípios; 2002–2023; VALIDADO_EXTERNAMENTE. Preços correntes; variação nominal. 2022/2023 sujeitos a revisão. Per capita: estimativas até 2021; Censo em 2022/2023. Evidências por ano no pacote e evidence store.');
  }
  function economicSectorChart(gt,canvasId,year) {
    const row=gt?.eixos?.economia?.pib_serie_historica?.find(s=>String(s.ano)===String(year));
    const fields=['servicos','industria','administracao','impostos','agro'];
    const labels=['Serviços (exceto administração pública)','Indústria','Administração, defesa, educação/saúde públicas e seguridade','Impostos líquidos de subsídios','Agropecuária'];
    const values=fields.map(k=>row?.components_mil_reais?.[k] == null || row?.pib_milhoes == null ? null : 100*row.components_mil_reais[k]/(row.pib_milhoes*1000));
    drawEconomicChart(canvasId,'doughnut',labels,[{label:'Participação no PIB (%)',data:values,backgroundColor:['#0D9488','#1D4ED8','#94A3B8','#64748B','#16A34A']}],
      `IBGE — ${year}; % do PIB a preços correntes. CALCULADO_A_PARTIR_DE_FONTES_OFICIAIS: 100 × componente / PIB. Administração e impostos separados. Abertura 2022/2023 não publicada; ausência preservada.`);
  }
  function updateEconomicCards(gt) {
    if (typeof window.updateEconomiaVisualCards === 'function') {
      window.updateEconomiaVisualCards(gt,RADAR_HUB_CACHE.package);
      return;
    }
    const summary=document.getElementById('hub-econ-audit-summary');
    const audited=Object.values(RADAR_HUB_CACHE.package?.economiaAudit?.indicators || {});
    if(summary) summary.textContent=`Economia — P1: ${audited.length} indicadores; ${audited.filter(a=>a.value!=null).length} com evidência externa (${audited.filter(a=>a.status==='CALCULADO_A_PARTIR_DE_FONTES_OFICIAIS').length} calculados), ${audited.filter(a=>a.value==null).length} não verificado. Revisão humana pendente. A auditoria global continua não carregada.`;
    const cempre = document.getElementById('hub-econ-cempre-reference');
    const locais = economicIndicator('econ_cempre_unidades_locais_2024'), orgs = economicIndicator('econ_cempre_organizacoes_2024');
    if(cempre) cempre.textContent = locais && orgs ? `IBGE CEMPRE — 2024: ${locais.value.toLocaleString('pt-BR')} unidades locais; ${orgs.value.toLocaleString('pt-BR')} empresas e outras organizações atuantes. VALIDADO_EXTERNAMENTE; universo distinto de CNPJs ativos; quebra metodológica em 2022.` : 'CEMPRE: dados não disponíveis.';
    for (const [id,element] of [['econ_pib_municipal_2023','hub-econ-pib-total'],['econ_pib_per_capita','hub-econ-pib-pc'],['econ_total_empresas_ativas','hub-econ-empresas']]) {
      const el=document.getElementById(element); const ind=economicIndicator(id);
      if(el) el.textContent=ind ? (id==='econ_pib_municipal_2023' ? 'R$ '+(ind.value/1000).toLocaleString('pt-BR',{maximumFractionDigits:2}) : 'R$ '+ind.value.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})) : 'Dado não disponível';
    }
    const stock=economicIndicator('econ_caged_estoque_2026_08'); const el=document.getElementById('hub-kpi-emprego');
    if(el) el.textContent=stock ? stock.value.toLocaleString('pt-BR') : 'Dado não disponível';
    const ref=document.getElementById('hub-kpi-emprego-reference');
    if(ref) ref.textContent=stock ? `MTE — ${stock.competencia}; vínculos; VALIDADO_EXTERNAMENTE; edição agosto/2026 com ajustes; 2026 parcial até agosto.` : 'Estoque não verificado nesta rodada.';
  }

  // G10-1: Economia - Evolução do PIB e PIB per Capita (IBGE)
  function renderEconomiaPibChart(gt) {
    updateEconomicCards(gt); economicPibChart(gt,'hubChartEconomiaPib',RADAR_HUB_CACHE.filterState.econ_pib?.tipo || 'total');
  }

  // G10-2: Economia - Geração de Emprego Novo CAGED (Toggle Mensal / Anual)
  function renderEconomiaEmpregoChart(gt) {
    const econ=gt?.eixos?.economia; const serie=econ?.novo_caged_serie_mensal || [];
    const filter=RADAR_HUB_CACHE.filterState.econ_caged || {}; const mode=filter.mode || 'mensal';
    const years=[...new Set(serie.map(r=>String(r.ano)))].sort();
    const selected=years.includes(String(filter.ano)) ? String(filter.ano) : years.at(-1);
    const select=document.getElementById('hub-econ-caged-year');
    if(select) { select.innerHTML=years.map(y=>`<option value="${y}">${serie.filter(r=>String(r.ano)===y).length<12 ? y+' parcial' : y}</option>`).join('');select.value=selected;select.disabled=mode==='anual'; }
    const metricSelect=document.getElementById('hub-econ-caged-metric');
    if(metricSelect) metricSelect.disabled=mode==='anual';
    const metric=['saldo','estoque','admissoes','desligamentos'].includes(filter.metrica) ? filter.metrica : 'saldo';
    const rows=mode==='anual' ? econ?.emprego_formal_novo_caged?.saldo_anual_historico || [] : serie.filter(r=>String(r.ano)===selected);
    const labels=rows.map(r=>mode==='anual'?String(r.ano)+(r.parcial?' parcial até agosto':''):r.competencia);
    const values=rows.map(r=>r[mode==='anual'?'saldo':metric] ?? null);
    drawEconomicChart('hubChartEconomiaEmprego','bar',labels,[{label:mode==='anual'?'Saldo anual (vínculos líquidos)':metric+' (vínculos / movimentações)',data:values,backgroundColor:values.map(v=>v==null?'#CBD5E1':v>=0?'#0D9488':'#EF4444'),borderRadius:6}],
      `MTE — Novo CAGED, Tabela 8.1; ${mode==='anual'?'2020–2026 (2026 parcial)':selected}; edição agosto/2026 com ajustes. ${mode==='anual'?'2020–2025 calculados pela soma dos 12 meses; 2026 acumulado janeiro–agosto publicado diretamente':'VALIDADO_EXTERNAMENTE; estoque publicado diretamente'}. Revisões incorporadas até a edição agosto/2026; posteriores não verificadas. Não concatenado à RAIS/CAGED antigo.`);
  }

